<script setup lang="ts">import {computed,ref} from "vue";import {Eye} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import SearchInput from "@/components/zs/SearchInput.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import SidePanel from "@/components/zs/SidePanel.vue";import ZButton from "@/components/zs/ZButton.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {setPageMeta} from "@/lib/page-meta";import type {AuditEvent} from "@/types/operations";setPageMeta("Audit Log","Immutable company activity history with before-and-after evidence.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.audit(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),q=ref(""),module=ref("All modules"),selected=ref<AuditEvent|null>(null),rows=computed(()=>(s.data.value??[]).filter(x=>(module.value==='All modules'||x.module===module.value)&&`${x.user} ${x.action} ${x.record}`.toLowerCase().includes(q.value.toLowerCase())));const columns:Column[]=[{key:"timestamp",header:"Time"},{key:"user",header:"User"},{key:"module",header:"Module"},{key:"action",header:"Action"},{key:"record",header:"Record"},{key:"result",header:"Result"},{key:"detail",header:""}];</script><template><AppShell><PageHeader title="Audit Log" description="Read-only history scoped to the active company"/><Panel><Toolbar><SearchInput v-model="q" placeholder="Search user, action or record"/><select v-model="module" class="field w-44"><option>All modules</option><option>Accounting</option><option>Purchases</option><option>CRM</option><option>Payroll</option></select><input type="date" class="field w-36"/><input type="date" class="field w-36"/></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1050"><template #timestamp="{row}:{row:AuditEvent}"><span class="num text-xs">{{new Date(row.timestamp).toLocaleString('en-GB')}}</span></template><template #user="{row}">{{row.user}}</template><template #module="{row}">{{row.module}}</template><template #action="{row}"><span class="font-medium text-content">{{row.action}}</span></template><template #record="{row}">{{row.record}}</template><template #result="{row}"><StatusBadge :status="row.result"/></template><template #detail="{row}"><ZButton variant="ghost" aria-label="View change details" @click="selected=row"><Eye class="size-4"/></ZButton></template></DataTable></Panel><SidePanel :open="!!selected" title="Audit event" :description="selected?.record" @close="selected=null"><div v-if="selected" class="space-y-5"><div><p class="label-caps">Action</p><p class="mt-1 text-sm text-content">{{selected.action}}</p><p class="mt-1 text-xs text-content-muted">{{selected.user}} · {{new Date(selected.timestamp).toLocaleString('en-GB')}}</p></div><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-md bg-surface-sunken p-3"><p class="label-caps">Before</p><p class="mt-2 text-xs text-content-secondary">{{selected.before??'No prior value'}}</p></div><div class="rounded-md bg-surface-sunken p-3"><p class="label-caps">After</p><p class="mt-2 text-xs text-content-secondary">{{selected.after??'No resulting value'}}</p></div></div><p class="text-xs text-content-muted">Audit records are read-only and retained by the authoritative backend.</p></div></SidePanel></AppShell></template>